library(shiny)
library(leaflet) 

server <- function(input, output, session) {
  
  # Run your external map script file
  source("~/Malaria/Lex/Website Visuals/Global Malaria Incidence Interactive Map Ready to Go.R", local = TRUE)
  
  # Send the map object generated by that file directly to the UI's placeholder container
  output$Malaria_webpage_Foundation <- renderLeaflet({
    # Change "my_final_map" to whatever your map object is called inside that file
    Global-Malaria-Incidence-Interactive-Map-Ready-to-Go.R
  })
  
}